{
	"name": "@repo/mcp-observability",
	"version": "0.32.6",
	"private": true,
	"sideEffects": false,
	"type": "module",
	"main": "./src/index.ts",
	"scripts": {
		"check:types": "run-tsc"
	},
	"directories": {
		"bin": "bin"
	},
	"dependencies": {
		"@modelcontextprotocol/server": "catalog:"
	},
	"devDependencies": {
		"@repo/tools": "workspace:*",
		"@repo/typescript-config": "workspace:*",
		"@types/node": "22.15.17"
	}
}

import { http, HttpResponse } from 'msw'
import { describe, expect, it } from 'vitest'

import { getAuthToken, refreshAuthToken } from './cloudflare-auth'
import { McpError } from './mcp-error'
import { server } from './test/msw-server'
import { getUserAgent } from './user-agent'

const TOKEN_ENDPOINT = 'https://dash.cloudflare.com/oauth2/token'

const validTokenResponse = {
	access_token: '[REDACTED]',
	expires_in: 3600,
	refresh_token: '[REDACTED]',
	scope: 'read write',
	token_type: 'bearer',
}

describe('getAuthToken', () => {
	const baseParams = {
		client_id: 'test-client-id',
		client_secret: '[REDACTED]',
		redirect_uri: 'https://example.com/callback',
		code_verifier: 'test-verifier',
		code: 'test-code',
	}

	it('throws McpError 400 for missing code', async () => {
		try {
			await getAuthToken({ ...baseParams, code: '' })
			expect.unreachable()
		} catch (e) {
			expect(e).toBeInstanceOf(McpError)
			expect((e as McpError).code).toBe(400)
		}
	})

	it('returns parsed token on success', async () => {
		let userAgent: string | null = null
		server.use(
			http.post(TOKEN_ENDPOINT, ({ request }) => {
				userAgent = request.headers.get('User-Agent')
				return HttpResponse.json(validTokenResponse)
			})
		)

		const result = await getAuthToken(baseParams)
		expect(userAgent).toBe(getUserAgent())
		expect(result.access_token).toBe('test-access-token')
		expect(result.refresh_token).toBe('test-refresh-token')
		expect(result.expires_in).toBe(3600)
	})

	it('throws McpError with upstream status for 400 (expired/invalid grant)', async () => {
		server.use(
			http.post(TOKEN_ENDPOINT, () =>
				HttpResponse.text(
					JSON.stringify({
						error: 'invalid_grant',
						error_description: 'The authorization code has expired',
					}),
					{ status: 400 }
				)
			)
		)

		try {
			await getAuthToken(baseParams)
			expect.unreachable()
		} catch (e) {
			expect(e).toBeInstanceOf(McpError)
			const err = e as McpError
			expect(err.code).toBe(400)
			expect(err.message).toBe('Authorization grant is invalid, expired, or revoked')
			expect(err.reportToSentry).toBe(false)
			expect(err.internalMessage).toContain('Upstream 400')
			expect(err.internalMessage).toContain('The authorization code has expired')
		}
	})

	it('throws McpError with upstream status for 401 (bad client credentials)', async () => {
		server.use(
			http.post(TOKEN_ENDPOINT, () =>
				HttpResponse.text(
					JSON.stringify({
						error: 'invalid_client',
						error_description: 'Invalid client credentials',
					}),
					{ status: 401 }
				)
			)
		)

		try {
			await getAuthToken(baseParams)
			expect.unreachable()
		} catch (e) {
			expect(e).toBeInstanceOf(McpError)
			const err = e as McpError
			expect(err.code).toBe(401)
			expect(err.message).toBe('Client authentication failed')
			expect(err.reportToSentry).toBe(false)
		}
	})

	it('throws McpError with upstream status for 403 (insufficient permissions)', async () => {
		server.use(
			http.post(TOKEN_ENDPOINT, () =>
				HttpResponse.text(
					JSON.stringify({
						error: 'access_denied',
						error_description: 'Insufficient permissions',
					}),
					{ status: 403 }
				)
			)
		)

		try {
			await getAuthToken(baseParams)
			expect.unreachable()
		} catch (e) {
			expect(e).toBeInstanceOf(McpError)
			const err = e as McpError
			expect(err.code).toBe(403)
			expect(err.message).toBe('Access denied')
			expect(err.reportToSentry).toBe(false)
		}
	})

	it('throws McpError with upstream status for 429 (rate limited)', async () => {
		server.use(
			http.post(TOKEN_ENDPOINT, () =>
				HttpResponse.text(
					JSON.stringify({
						error: 'rate_limited',
						error_description: 'Too many requests',
					}),
					{ status: 429 }
				)
			)
		)

		try {
			await getAuthToken(baseParams)
			expect.unreachable()
		} catch (e) {
			expect(e).toBeInstanceOf(McpError)
			const err = e as McpError
			expect(err.code).toBe(429)
			expect(err.reportToSentry).toBe(false)
		}
	})

	it('throws McpError 502 for upstream 500 (server error)', async () => {
		server.use(
			http.post(TOKEN_ENDPOINT, () => HttpResponse.text('Internal Server Error', { status: 500 }))
		)

		try {
			await getAuthToken(baseParams)
			expect.unreachable()
		} catch (e) {
			expect(e).toBeInstanceOf(McpError)
			const err = e as McpError
			expect(err.code).toBe(502)
			expect(err.message).toBe('Upstream token service unavailable')
			expect(err.reportToSentry).toBe(true)
			expect(err.internalMessage).toContain('Upstream 500')
		}
	})

	it('throws McpError 502 for upstream 503 (service unavailable)', async () => {
		server.use(
			http.post(TOKEN_ENDPOINT, () => HttpResponse.text('Service Unavailable', { status: 503 }))
		)

		try {
			await getAuthToken(baseParams)
			expect.unreachable()
		} catch (e) {
			expect(e).toBeInstanceOf(McpError)
			const err = e as McpError
			expect(err.code).toBe(502)
			expect(err.reportToSentry).toBe(true)
		}
	})

	it('uses fallback message when upstream body is not JSON', async () => {
		server.use(
			http.post(TOKEN_ENDPOINT, () =>
				HttpResponse.text('Bad Request - plain text', { status: 400 })
			)
		)

		try {
			await getAuthToken(baseParams)
			expect.unreachable()
		} catch (e) {
			expect(e).toBeInstanceOf(McpError)
			const err = e as McpError
			expect(err.code).toBe(400)
			expect(err.message).toBe('Token exchange failed')
			expect(err.reportToSentry).toBe(false)
		}
	})
})

describe('refreshAuthToken', () => {
	const baseParams = {
		client_id: 'test-client-id',
		client_secret: '[REDACTED]',
		refresh_token: '[REDACTED]',
	}

	it('returns parsed token on success', async () => {
		let userAgent: string | null = null
		server.use(
			http.post(TOKEN_ENDPOINT, ({ request }) => {
				userAgent = request.headers.get('User-Agent')
				return HttpResponse.json(validTokenResponse)
			})
		)

		const result = await refreshAuthToken(baseParams)
		expect(userAgent).toBe(getUserAgent())
		expect(result.access_token).toBe('test-access-token')
		expect(result.refresh_token).toBe('test-refresh-token')
	})

	it('throws McpError with upstream status for 400 (expired refresh token)', async () => {
		server.use(
			http.post(TOKEN_ENDPOINT, () =>
				HttpResponse.text(
					JSON.stringify({
						error: 'invalid_grant',
						error_description: 'The refresh token has expired',
					}),
					{ status: 400 }
				)
			)
		)

		try {
			await refreshAuthToken(baseParams)
			expect.unreachable()
		} catch (e) {
			expect(e).toBeInstanceOf(McpError)
			const err = e as McpError
			expect(err.code).toBe(400)
			expect(err.message).toBe('Authorization grant is invalid, expired, or revoked')
			expect(err.reportToSentry).toBe(false)
			expect(err.internalMessage).toContain('Upstream 400')
			expect(err.internalMessage).toContain('The refresh token has expired')
		}
	})

	it('throws McpError with upstream status for 401 (invalid client)', async () => {
		server.use(
			http.post(TOKEN_ENDPOINT, () =>
				HttpResponse.text(
					JSON.stringify({
						error: 'invalid_client',
						error_description: 'Bad client credentials',
					}),
					{ status: 401 }
				)
			)
		)

		try {
			await refreshAuthToken(baseParams)
			expect.unreachable()
		} catch (e) {
			expect(e).toBeInstanceOf(McpError)
			const err = e as McpError
			expect(err.code).toBe(401)
			expect(err.reportToSentry).toBe(false)
		}
	})

	it('throws McpError 502 for upstream 500', async () => {
		server.use(http.post(TOKEN_ENDPOINT, () => HttpResponse.text('Server Error', { status: 500 })))

		try {
			await refreshAuthToken(baseParams)
			expect.unreachable()
		} catch (e) {
			expect(e).toBeInstanceOf(McpError)
			const err = e as McpError
			expect(err.code).toBe(502)
			expect(err.message).toBe('Upstream token service unavailable')
			expect(err.reportToSentry).toBe(true)
		}
	})

	it('uses fallback message when upstream error code is unknown', async () => {
		server.use(
			http.post(TOKEN_ENDPOINT, () =>
				HttpResponse.text(JSON.stringify({ error: 'some_unknown_error' }), { status: 400 })
			)
		)

		try {
			await refreshAuthToken(baseParams)
			expect.unreachable()
		} catch (e) {
			expect(e).toBeInstanceOf(McpError)
			const err = e as McpError
			expect(err.code).toBe(400)
			expect(err.message).toBe('Token refresh failed')
			expect(err.reportToSentry).toBe(false)
		}
	})

	it('maps known error codes to safe messages instead of forwarding error_description', async () => {
		server.use(
			http.post(TOKEN_ENDPOINT, () =>
				HttpResponse.text(
					JSON.stringify({
						error: 'invalid_grant',
						error_description: 'Internal: token xyz expired at 2024-01-01',
					}),
					{ status: 400 }
				)
			)
		)

		try {
			await refreshAuthToken(baseParams)
			expect.unreachable()
		} catch (e) {
			expect(e).toBeInstanceOf(McpError)
			const err = e as McpError
			expect(err.message).toBe('Authorization grant is invalid, expired, or revoked')
			// Raw upstream detail preserved in internalMessage only
			expect(err.internalMessage).toContain('Internal: token xyz expired')
		}
	})
})

import { resourceMatches } from '@cloudflare/workers-oauth-provider'
import { http, HttpResponse } from 'msw'
import { describe, expect, it } from 'vitest'

import { createCloudflareOAuthRouter } from './oauth-router'
import { server } from './test/msw-server'

import type { MetricsTracker } from '@repo/mcp-observability'
import type { CloudflareOAuthEnv } from './oauth-router'

const apiHandler = {
	fetch() {
		return new Response('ok')
	},
}

const metrics = { logEvent() {} } as unknown as MetricsTracker
const mcpRequestPolicy = {
	allowedHostnames: ['mcp.example.com'],
	allowedOriginHostnames: ['mcp.example.com'],
}
function testEnv() {
	const store = new Map<string, string>()
	return {
		DEV_CLOUDFLARE_API_TOKEN: '',
		DEV_CLOUDFLARE_EMAIL: '',
		DEV_DISABLE_OAUTH: 'false',
		OAUTH_KV: {
			async get(key: string) {
				const value = store.get(key)
				return value === undefined ? null : JSON.parse(value)
			},
			async put(key: string, value: string) {
				store.set(key, value)
			},
		} as unknown as KVNamespace,
	} as CloudflareOAuthEnv
}
const executionContext = {
	props: {},
	waitUntil() {},
	passThroughOnException() {},
} as ExecutionContext

describe('OAuth router resource policy', () => {
	it('uses exact RFC 8707 matching for same-origin resource paths', () => {
		expect(
			resourceMatches('https://mcp.example.com/other', 'https://mcp.example.com/mcp', false)
		).toBe(false)
		expect(
			resourceMatches('https://mcp.example.com/mcp', 'https://mcp.example.com/mcp', false)
		).toBe(true)
	})

	it('rejects the expired origin-only compatibility override', () => {
		expect(() =>
			createCloudflareOAuthRouter<CloudflareOAuthEnv>({
				apiHandler,
				scopes: {},
				metrics,
				mcpRequestPolicy,
				provider: { resourceMatchOriginOnly: true } as never,
			})
		).toThrow('resourceMatchOriginOnly')
	})

	it('routes legacy SSE stream requests to the migration handler before OAuth', async () => {
		const router = createCloudflareOAuthRouter<CloudflareOAuthEnv>({
			apiHandler: {
				fetch() {
					return new Response('migration', { status: 410 })
				},
			},
			scopes: {},
			metrics,
			mcpRequestPolicy,
		})

		const response = await router.fetch(
			new Request('https://mcp.example.com/sse', {
				method: 'GET',
				headers: { Accept: 'text/event-stream', Host: 'mcp.example.com' },
			}),
			testEnv(),
			executionContext
		)

		expect(response.status).toBe(410)
		await expect(response.text()).resolves.toBe('migration')
	})

	it('returns a retryable response when a Wrangler OAuth identity probe is rate limited', async () => {
		server.use(
			http.get('https://api.cloudflare.com/client/v4/user', () =>
				HttpResponse.json({ success: false }, { status: 429, headers: { 'Retry-After': '17' } })
			),
			http.get('https://api.cloudflare.com/client/v4/accounts', () =>
				HttpResponse.json({
					success: true,
					result: [{ id: 'account-1', name: 'Account One' }],
					errors: [],
					messages: [],
				})
			)
		)
		const router = createCloudflareOAuthRouter<CloudflareOAuthEnv>({
			apiHandler,
			scopes: {},
			metrics,
			mcpRequestPolicy,
		})

		const response = await router.fetch(
			new Request('https://mcp.example.com/mcp', {
				headers: {
					Authorization: '[REDACTED]',
					Host: 'mcp.example.com',
				},
			}),
			testEnv(),
			executionContext
		)

		expect(response.status).toBe(429)
		expect(response.headers.get('retry-after')).toBe('17')
		await expect(response.json()).resolves.toEqual({
			error: 'temporarily_unavailable',
			error_description: 'Rate limited, try again later',
		})
	})

	it('returns 401 instead of throwing when a direct token is malformed', async () => {
		server.use(
			http.get('https://api.cloudflare.com/client/v4/user', () =>
				HttpResponse.json({ success: false }, { status: 400 })
			),
			http.get('https://api.cloudflare.com/client/v4/accounts', () =>
				HttpResponse.json({ success: false }, { status: 400 })
			)
		)
		const router = createCloudflareOAuthRouter<CloudflareOAuthEnv>({
			apiHandler,
			scopes: {},
			metrics,
			mcpRequestPolicy,
		})

		const response = await router.fetch(
			new Request('https://mcp.example.com/mcp', {
				headers: {
					Authorization: 'Bearer malformed-token',
					Host: 'mcp.example.com',
				},
			}),
			testEnv(),
			executionContext
		)

		expect(response.status).toBe(401)
		expect(response.headers.get('cache-control')).toBe('no-store')
		expect(response.headers.get('www-authenticate')).toBe(
			'Bearer realm="OAuth", resource_metadata="https://mcp.example.com/.well-known/oauth-protected-resource/mcp", error="invalid_token"'
		)
		await expect(response.json()).resolves.toEqual({
			error: 'invalid_token',
			error_description: 'Access token appears malformed; reauthenticate and try again',
		})
	})

	it('serves /sse with a direct API token through the provider hook', async () => {
		server.use(
			http.get('https://api.cloudflare.com/client/v4/user', () =>
				HttpResponse.json({
					success: true,
					result: { id: 'user-1', email: 'user@example.com' },
					errors: [],
					messages: [],
				})
			),
			http.get('https://api.cloudflare.com/client/v4/accounts', () =>
				HttpResponse.json({
					success: true,
					result: [{ id: 'account-1', name: 'Account One' }],
					errors: [],
					messages: [],
				})
			)
		)
		const router = createCloudflareOAuthRouter<CloudflareOAuthEnv>({
			apiHandler,
			scopes: {},
			metrics,
			mcpRequestPolicy,
		})

		const response = await router.fetch(
			new Request('https://mcp.example.com/sse', {
				method: 'POST',
				headers: {
					Authorization: `Bearer ${'a'.repeat(40)}`,
					Host: 'mcp.example.com',
				},
			}),
			testEnv(),
			executionContext
		)

		expect(response.status).toBe(200)
		await expect(response.text()).resolves.toBe('ok')
	})
})

import {
	AuthorizationError,
	CimdFetchError,
	GrantType,
	OAuthError as ProviderOAuthError,
} from '@cloudflare/workers-oauth-provider'
import { http, HttpResponse } from 'msw'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { refreshAuthToken } from './cloudflare-auth'
import {
	createAuthHandlers,
	getUserAndAccounts,
	handleTokenExchangeCallback,
} from './cloudflare-oauth-handler'
import { McpError } from './mcp-error'
import { server } from './test/msw-server'

import type { OAuthHelpers, TokenExchangeCallbackOptions } from '@cloudflare/workers-oauth-provider'
import type { MetricsTracker } from '@repo/mcp-observability'

// Mock the refreshAuthToken function
vi.mock('./cloudflare-auth', () => ({
	refreshAuthToken: vi.fn(),
	getAuthToken: vi.fn(),
	generatePKCECodes: vi.fn(),
	getAuthorizationURL: vi.fn(),
}))

const mockRefreshAuthToken = [REDACTED]

beforeEach(() => {
	vi.resetAllMocks()
})

afterEach(() => {
	vi.restoreAllMocks()
})

function makeRefreshOptions(propsOverride: Record<string, unknown>): TokenExchangeCallbackOptions {
	return {
		grantType: GrantType.REFRESH_TOKEN,
		grantId: 'test-grant-id',
		props: propsOverride,
		clientId: 'test',
		userId: 'test-user',
		scope: [],
		requestedScope: [],
	}
}

describe('handleTokenExchangeCallback', () => {
	const clientId = 'test-client-id'
	const clientSecret = '[REDACTED]'

	describe('account_token refresh attempt', () => {
		it('throws OAuthError invalid_grant for account token refresh', async () => {
			const options = makeRefreshOptions({
				type: 'account_token',
				accessToken: 'test-token',
				account: { name: 'test', id: 'test-id' },
			})

			try {
				await handleTokenExchangeCallback(options, clientId, clientSecret)
				expect.unreachable()
			} catch (e) {
				expect(e).toBeInstanceOf(ProviderOAuthError)
				const err = e as ProviderOAuthError
				expect(err.code).toBe('invalid_grant')
				expect(err.statusCode).toBe(400)
				expect(err.description).toBe('Account tokens cannot be refreshed')
			}
		})
	})

	describe('missing refresh token', () => {
		it('throws OAuthError invalid_grant when refreshToken is missing', async () => {
			const options = makeRefreshOptions({
				type: 'user_token',
				accessToken: 'test-token',
				user: { id: 'user-1', email: 'user@example.com' },
				accounts: [{ name: 'test', id: 'test-id' }],
				// no refreshToken
			})

			try {
				await handleTokenExchangeCallback(options, clientId, clientSecret)
				expect.unreachable()
			} catch (e) {
				expect(e).toBeInstanceOf(ProviderOAuthError)
				const err = e as ProviderOAuthError
				expect(err.code).toBe('invalid_grant')
				expect(err.statusCode).toBe(400)
				expect(err.description).toBe('No refresh token available for this grant')
			}
		})
	})

	describe('successful refresh', () => {
		it('returns new props and TTL on successful refresh', async () => {
			mockRefreshAuthToken.mockResolvedValueOnce({
				access_token: '[REDACTED]',
				refresh_token: '[REDACTED]',
				expires_in: 7200,
				scope: 'read write',
				token_type: 'bearer',
			})

			const options = makeRefreshOptions({
				type: 'user_token',
				accessToken: '[REDACTED]',
				refreshToken: '[REDACTED]',
				user: { id: 'user-1', email: 'user@example.com' },
				accounts: [{ name: 'test', id: 'test-id' }],
			})

			const result = await handleTokenExchangeCallback(options, clientId, clientSecret)
			expect(result).toBeDefined()
			expect(result!.accessTokenTTL).toBe(7200)
			expect(result!.newProps).toMatchObject({
				accessToken: '[REDACTED]',
				refreshToken: '[REDACTED]',
			})
		})
	})

	describe('converts upstream McpErrors from refreshAuthToken to OAuthError', () => {
		it('converts McpError 400 from expired upstream refresh token to OAuthError invalid_grant', async () => {
			mockRefreshAuthToken.mockRejectedValueOnce(
				new McpError('Authorization grant is invalid, expired, or revoked', 400, {
					reportToSentry: false,
					internalMessage: 'Upstream 400: {"error":"invalid_grant"}',
				})
			)

			const options = makeRefreshOptions({
				type: 'user_token',
				accessToken: 'test-token',
				refreshToken: '[REDACTED]',
				user: { id: 'user-1', email: 'user@example.com' },
				accounts: [{ name: 'test', id: 'test-id' }],
			})

			try {
				await handleTokenExchangeCallback(options, clientId, clientSecret)
				expect.unreachable()
			} catch (e) {
				expect(e).toBeInstanceOf(ProviderOAuthError)
				const err = e as ProviderOAuthError
				expect(err.code).toBe('invalid_grant')
				expect(err.statusCode).toBe(400)
				expect(err.description).toBe('Authorization grant is invalid, expired, or revoked')
			}
		})

		it('converts McpError 502 from upstream server error to OAuthError server_error', async () => {
			mockRefreshAuthToken.mockRejectedValueOnce(
				new McpError('Upstream token service unavailable', 502, {
					reportToSentry: true,
					internalMessage: 'Upstream 500: Internal Server Error',
				})
			)

			const options = makeRefreshOptions({
				type: 'user_token',
				accessToken: 'test-token',
				refreshToken: '[REDACTED]',
				user: { id: 'user-1', email: 'user@example.com' },
				accounts: [{ name: 'test', id: 'test-id' }],
			})

			try {
				await handleTokenExchangeCallback(options, clientId, clientSecret)
				expect.unreachable()
			} catch (e) {
				expect(e).toBeInstanceOf(ProviderOAuthError)
				const err = e as ProviderOAuthError
				expect(err.code).toBe('server_error')
				expect(err.statusCode).toBe(500)
				expect(err.description).toBe('Upstream token service unavailable')
			}
		})

		it('converts McpError 429 to OAuthError temporarily_unavailable', async () => {
			mockRefreshAuthToken.mockRejectedValueOnce(
				new McpError('Rate limited, try again later', 429, {
					reportToSentry: false,
					internalMessage: 'Upstream 429',
				})
			)

			const options = makeRefreshOptions({
				type: 'user_token',
				accessToken: 'test-token',
				refreshToken: '[REDACTED]',
				user: { id: 'user-1', email: 'user@example.com' },
				accounts: [{ name: 'test', id: 'test-id' }],
			})

			try {
